-- Import National technician assessments from Microsoft Forms export
-- Source: Natl Responses - TAB Skills Self-Assessment.xlsx
-- PREREQ: run supabase/assessments-rpcs.sql first — or use natl-assessments-fix-now.sql (all-in-one).
-- Safe to re-run. No temp tables. No ON CONFLICT.

-- === IMPORT DATA ===
SELECT app_upsert_assessment_for_tech(
  app_match_technician_id(v.tech_name, 'National'),
  CASE
    WHEN v.mode = 'latest' THEN coalesce(
      (SELECT max(a.date)
       FROM public.assessments a
       WHERE a.technician_id = app_match_technician_id(v.tech_name, 'National')),
      v.fallback_date::date
    )
    ELSE v.assessment_date::date
  END,
  v.safety_avg,
  v.basic_avg,
  v.intermediate_avg,
  v.advanced_avg,
  v.survey_avg,
  v.comment,
  v.raw_scores
)
